CREATE TABLE `agent_hierarchy` (
  `ID` bigint NOT NULL AUTO_INCREMENT,
  `AgentID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理账号',
  `ParentID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上级代理',
  `Level` int NOT NULL COMMENT '层级 1-8',
  `Path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '层级路径 如: admin/agent1/agent2',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `idx_agent` (`AgentID`) USING BTREE,
  KEY `idx_parent` (`ParentID`) USING BTREE,
  KEY `idx_level` (`Level`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代理层级关系表';
