  `IsFrozen` int DEFAULT '1',
  `IsProbability` int DEFAULT '0',
  `IsKicking` int DEFAULT '1',
  `KickScope` int DEFAULT '1',
  `IsDelete` int DEFAULT '0',
  `IsGift` int DEFAULT '0',
  `IsCreateAgent` int DEFAULT '0',
  `IsViewPwd` int DEFAULT '0',
  `IsModifyPwd` int DEFAULT '0',
