  `IsRelease` int NOT NULL DEFAULT '0' COMMENT '注机放水权限',
  `IsCardKill` int NOT NULL DEFAULT '0' COMMENT '牌机点杀权限',
  `IsCardRelease` int NOT NULL DEFAULT '0' COMMENT '牌机放水权限',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `idx_level` (`Level`) USING BTREE
