--
-- Table structure for table `clientexchangerecord`
--

DROP TABLE IF EXISTS `clientexchangerecord`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `clientexchangerecord` (
  `CRID` int unsigned NOT NULL AUTO_INCREMENT COMMENT '标识ID',
  `ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户账号',
  `Coins` bigint NOT NULL COMMENT '下分',
  `WxPay` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '用户微信号',
  `AliPayName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '支付宝账户名',
  `AliPay` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '用户支付宝号',
  `AccountName` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '银行账户名',
  `BankAccount` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '用户银行账号',
  `BankName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '开户银行名称',
  `BranchBankName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '开户支行名称',
  `Processed` int DEFAULT '0' COMMENT '处理状态 0未处理 1确认下分 2取消下分 3服务器已处理',
