DROP TABLE IF EXISTS `rechargerecords`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rechargerecords` (
  `OrderNo` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `RechargeType` int DEFAULT NULL COMMENT '充值类型 1微信 2支付宝',
  `Coin` bigint DEFAULT NULL COMMENT '充值数量',
  `BEF_COINS` bigint DEFAULT '0' COMMENT '充值前金币',
  `AFT_COINS` bigint DEFAULT '0' COMMENT '充值后金币',
  `GameID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '玩家游戏ID',
  `AccountType` int DEFAULT '0' COMMENT '账号类型  0玩家  1代理',
  `Agency` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '代理ID',
  `PayNo` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '付款账号',
  `Processed` int DEFAULT '0' COMMENT '处理状态 0未处理 1已处理 2拒绝处理',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `Operator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`OrderNo`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='充值记录信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

