DROP TABLE IF EXISTS `roomtableconfig`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `roomtableconfig` (
  `ID` int NOT NULL AUTO_INCREMENT COMMENT '唯一自增主键',
  `GAME_ID` int NOT NULL COMMENT '关联的游戏ID',
  `RoomIndex` int NOT NULL COMMENT '房间号',
  `TableIndex` int NOT NULL DEFAULT '-1' COMMENT '桌号（-1表示该房通用）',
  `TableName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '独立桌名显示',
  `SeatCount` int NOT NULL DEFAULT '4' COMMENT '桌台座位上限数（支持4人/6人）',
  `ExchangeRate` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1:1' COMMENT '游戏兑换比率',
  `MinBringIn` bigint NOT NULL DEFAULT '0' COMMENT '最小带入金币',
  `MaxBringIn` bigint NOT NULL DEFAULT '0' COMMENT '最大带入金币（0为不设限）',
  `IdleFireTimeoutSec` int NOT NULL DEFAULT '0' COMMENT '无发炮踢出秒数，0=不踢',
  `IdleFireKickEnabled` int NOT NULL DEFAULT '0' COMMENT '是否启用踢出机制 (0/1)',
  `MinBetUnits` int NOT NULL DEFAULT '0' COMMENT '最小下注/炮值（缩放整数格式）',
  `DifScaled` int NOT NULL DEFAULT '0' COMMENT '难度（缩放整数）',
  `Enabled` int NOT NULL DEFAULT '1' COMMENT '启用/隐藏状态',
  `MaxSeats` int NOT NULL DEFAULT '6' COMMENT '??????0=?????6=?????8=????',
  `OneCoinScore` int NOT NULL DEFAULT '0',
  `BetMin` int NOT NULL DEFAULT '0',
  `BetMax` int NOT NULL DEFAULT '0',
  `CoinsNeed` int NOT NULL DEFAULT '0',
  `GunPowerStep` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `idx_game_room_table` (`GAME_ID`,`RoomIndex`,`TableIndex`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5300850 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='动态桌台配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

