  `GAME_ID` int NOT NULL COMMENT '游戏ID',
  `RoomIndex` int NOT NULL DEFAULT '0' COMMENT '房间索引（大厅废除后恒0）',
  `TableIndex` int NOT NULL COMMENT '桌台全局索引',
  `BetTime` int NOT NULL DEFAULT '0' COMMENT '押注时长(秒)',
  `BetMin` int NOT NULL DEFAULT '0' COMMENT '本桌最小押注',
  `BetMax` int NOT NULL DEFAULT '0' COMMENT '本桌最大押注',
  `BankerScoreNeed` int NOT NULL DEFAULT '0' COMMENT '抢庄分数门槛/DT全台敞口上限',
  `ItemSingleScoreLimit` int NOT NULL DEFAULT '0' COMMENT '单门限红(DT填0不校验)',
  `ItemAllScoreLimit` int NOT NULL DEFAULT '0' COMMENT '全台限红(DT填0不校验)',
