  `BetMaxVice` int NOT NULL DEFAULT '0' COMMENT '副玩法大小最大押注(仅Animal)',
  `BetMinDraw` int NOT NULL DEFAULT '0' COMMENT '副玩法和最小押注(仅Animal)',
  `BetMaxDraw` int NOT NULL DEFAULT '0' COMMENT '副玩法和最大押注(仅Animal)',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `idx_game_table` (`GAME_ID`,`TableIndex`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='押注类桌台扩展参数表(按桌)';
