DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户账号',
  `NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户昵称',
  `PWD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码',
  `AGENCY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '代理账号',
  `PIC_INDEX` int DEFAULT '0' COMMENT '头像索引',
  `FROZEN` int DEFAULT '0' COMMENT '冻结  0不冻结  1冻结',
  `COINS` bigint DEFAULT '0' COMMENT '金币',
  `COINS_EXP` bigint DEFAULT '0',
  `COINS_BUY` bigint DEFAULT '0',
  `COINS_BACK` bigint DEFAULT '0',
  `VIDEOGAMEID` int DEFAULT '-1',
  `WXHEADIMG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'nowxheadimg' COMMENT '微信头像',
  `SEX` int DEFAULT '1' COMMENT '性别  1男  2女',
  `LoginType` int DEFAULT '0' COMMENT '登录类型  0普通登录  1微信登录',
  `BMW_SCORE` bigint DEFAULT '0',
  `DICE_SCORE` bigint DEFAULT '0',
  `DT_SCORE` bigint DEFAULT '0',
  `PHENIX_SCORE` bigint DEFAULT '0',
  `JC_SCORE` bigint DEFAULT '0',
  `MAGNATE_SCORE` bigint DEFAULT '0',
  `FISH_COW_SCORE` bigint DEFAULT '0',
  `FISH_CROCODILE_SCORE` bigint DEFAULT '0',
  `CARD_ATT2_SCORE` bigint NOT NULL DEFAULT '0',
  `CARD_FISH_SCORE` bigint DEFAULT '0',
  `BET_ANIMAL_SCORE` bigint DEFAULT '0',
  `FISH_BIRD_SCORE` bigint DEFAULT '0',
  `BET_COW_SCORE` bigint DEFAULT '0',
  `TELEPHONE` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `INHALL` bit(1) DEFAULT b'0' COMMENT '在线状态',
  `IsRegister` bit(1) DEFAULT b'0' COMMENT '是否注册过视讯，0未注册，1注册',
  `GAME_SCORE` bigint DEFAULT '0',
  `SAFE_PWD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '123456' COMMENT '保险柜密码，默认123456',
  `SAFE_COINS` bigint DEFAULT '0' COMMENT '保险柜金币数量',
  `GRADE` int DEFAULT '1' COMMENT '等级，默认1',
  `CreateTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `Remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '后台备注',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

